/**
 * English (en-GB) for the messages the server sends when it refuses something (`{ error: … }`), and for the
 * field names its checks put into them ("Betreff fehlt" → "Subject is missing"). core/app.ts translates every error
 * answer for requests from the web app in English (header x-pghl-lang: en); everyone else keeps the German text.
 * Keys are the German texts in the code; `{v0}`, `{v1}` … stand for the values of a template literal. Generated from
 * the server's bad(), notFound(), HttpError and field-name calls; a message without an entry stays German.
 */
